// Reports: the GTT × Verint end-of-shift report (generated by local_api.py), with the
// Floor's own KPIs and alert outcomes folded in, so the PDF and the screen agree.
import { useState } from "react";
import type { Account } from "../data/accounts";
import type { Kpis } from "../domain/kpis";
import type { AdherenceSummary } from "../reports/types";
import { GttReportDashboard } from "../reports/GttReportDashboard";
import { ReportConfigPanel } from "../reports/ReportConfigPanel";
import type { useReports } from "../reports/useReports";
import "../reports/reports.css";

type Props = {
  account: Account | undefined;
  r: ReturnType<typeof useReports>;
  adherence: AdherenceSummary;
  alertAgents: string[];
  kpis: Kpis;
  asOf: number;
  hasRoster: boolean;
  onDigest: () => void;
};

export function Reports({ account, r, adherence, alertAgents, kpis, asOf, hasRoster, onDigest }: Props) {
  const [cfgOpen, setCfgOpen] = useState(false);
  if (!account || !r.config) return <p className="reports muted">Reports need a real account: pick one in the header.</p>;
  const running = r.gen.state === "running";

  return (
    <div className="reports">
      <div className="bar">
        <span className="muted">
          {r.report ? <>Last generated {new Date(r.report.generated_at).toLocaleString()}</> : <>No report for {account.label} in the last 3 days.</>}
          {r.gen.state === "error" && <span className="bad"> · Generate failed: {r.gen.error}</span>}
          {!hasRoster && <> · No Verint roster yet: the report will have GTT only.</>}
        </span>
        <span style={{ display: "flex", gap: 8 }}>
          <button onClick={() => setCfgOpen(true)}>Settings</button>
          <button className="primary" onClick={r.generate} disabled={running}>{running ? "Generating…" : "Generate now"}</button>
        </span>
      </div>
      {r.report && (
        <GttReportDashboard report={r.report} visibleColumns={r.config.visibleColumns} snapshotsToday={r.snapshots}
          adherence={adherence} alertAgents={alertAgents} kpis={kpis} kpisAsOf={asOf} accountLabel={account.label} onOpenConfig={() => setCfgOpen(true)} />
      )}
      {cfgOpen && (
        <ReportConfigPanel accountId={account.id} defaults={r.config} onClose={() => setCfgOpen(false)}
          onConfigSave={(cfg) => { r.setConfig(cfg); setCfgOpen(false); }} onSendChatDigestNow={onDigest} />
      )}
    </div>
  );
}
